use crate::fmt_num;

fmt_num! {
    #[doc = crate::_tags!(example num)]
    /// Example const number formatter generated by [`fmt_num!`].
    #[doc = crate::_doc_meta!{location("text/fmt", struct FmtNumExample)}]
    /// Demonstrates every method family on signed, unsigned and floating-point numbers.
    ///
    /// # Methods
    ///
    /// All methods are `const`, implemented for `u8`, `i32` and `f32`.
    ///
    /// - Writing:
    ///   [`write`](#method.write), [`write_fmt`](#method.write_fmt).
    /// - Measuring:
    ///   [`measure`](#method.measure), [`measure_fmt`](#method.measure_fmt).
    /// - Grouping:
    ///   [`write_group`](#method.write_group),
    ///   [`measure_group`](#method.measure_group).
    /// - Bytes:
    ///   [`as_bytes_into`](#method.as_bytes_into)
    ///   *([_fmt](#method.as_bytes_into_fmt),
    ///     [_checked](#method.as_bytes_into_checked),
    ///     [_checked_fmt](#method.as_bytes_into_checked_fmt))*.
    /// - Strings:
    ///   [`as_str_into`](#method.as_str_into)
    ///   *([_fmt](#method.as_str_into_fmt),
    ///     [_checked](#method.as_str_into_checked),
    ///     [_checked_fmt](#method.as_str_into_checked_fmt))*.
    /// - Owned strings:
    ///   [`as_string`](#method.as_string)
    ///   *([_fmt](#method.as_string_fmt),
    ///     [_checked](#method.as_string_checked),
    ///     [_checked_fmt](#method.as_string_checked_fmt))*.
    ///
    /// Floating-point methods without `_fmt` take an additional
    /// `fract_len: u16` argument to specify decimal precision.
    pub struct FmtNumExample: <> impl (u8, i32, f32); core, group, bytes, str, string
}
